INSERT INTO knowledge_articles (id, title, service, content, source_url, updated_at) VALUES
  ('KB-001', 'Reset a verified account password', 'Identity', 'Verify the requester using the approved identity check. Use the password reset workflow, ask the requester to enrol MFA after reset, and escalate any identity-verification failure.', 'https://www.ncsc.gov.uk/collection/top-tips-for-staying-secure-online/passwords', '2026-08-28T00:00:00.000Z'),
  ('KB-002', 'VPN connection troubleshooting', 'Network', 'Check network connectivity, confirm the VPN client is current, verify MFA approval, then collect diagnostic logs before routing unresolved cases to Network Support.', 'https://www.ncsc.gov.uk/guidance/home-working-preparing-your-organisation-and-staff', '2026-08-28T00:00:00.000Z'),
  ('KB-003', 'Outlook desktop application recovery', 'Collaboration', 'Confirm service status, restart the application, test web access, and capture the error message before escalating to Application Support.', 'https://support.microsoft.com/outlook', '2026-08-28T00:00:00.000Z');
